import sys

def solve():
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    grid = []
    idx = 2
    for i in range(n):
        grid.append(data[idx + i])
        idx += 1

    # Create a mutable grid to track which '*' are covered by stars
    # We'll use a separate 2D array of booleans, initially False, to mark covered cells
    covered = [[False for _ in range(m)] for _ in range(n)]

    # List to store valid stars
    stars = []

    # Iterate over every cell to check if it can be the center of a star
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '*':
                # Try to find the maximum possible size of a star centered at (r, c)
                # The size s means rays of length s extending up, down, left, right
                # Minimum size is 1
                max_s = 0
                possible = True

                # Check all four directions for the maximum contiguous '*' sequence
                # Up
                up = 0
                for dr in range(-1, -max_s - 1, -1):
                    nr, nc = r + dr, c
                    if 0 <= nr < n and grid[nr][nc] == '*':
                        up += 1
                    else:
                        break

                # Down
                down = 0
                for dr in range(1, n - r):
                    nr, nc = r + dr, c
                    if 0 <= nr < n and grid[nr][nc] == '*':
                        down += 1
                    else:
                        break

                # Left
                left = 0
                for dc in range(-1, -c - 1, -1):
                    nr, nc = r, c + dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '*':
                        left += 1
                    else:
                        break

                # Right
                right = 0
                for dc in range(1, m - c):
                    nr, nc = r, c + dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '*':
                        right += 1
                    else:
                        break

                # The size of the star is limited by the minimum of the four arms
                # Note: The problem defines size as the length of the rays.
                # If we have 1 cell above, 1 below, 1 left, 1 right, the ray length is 1.
                # So size = min(up, down, left, right)
                if up > 0 and down > 0 and left > 0 and right > 0:
                    s = min(up, down, left, right)
                    if s >= 1:
                        max_s = s

                # If a star of size max_s exists here, we add it
                # Why add it? Because we need to cover all '*' that are part of ANY star.
                # By greedily taking the largest possible star at every valid center,
                # we maximize coverage. If a '*' cannot be part of any star, then even with max coverage,
                # it will remain uncovered, leading to the correct "-1" result later.
                if max_s >= 1:
                    stars.append((r + 1, c + 1, max_s))
                    # Mark the star's area as covered
                    for dr in range(-max_s, max_s + 1):
                        for dc in range(-max_s, max_s + 1):
                            # Only mark the cross shape
                            if dr == 0 or dc == 0:
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < n and 0 <= nc < m:
                                    covered[nr][nc] = True

    # Now verify if every '*' in the original grid is covered
    can_draw = True
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '*':
                if not covered[r][c]:
                    can_draw = False
                    break
        if not can_draw:
            break

    if not can_draw:
        print("-1")
    else:
        print(len(stars))
        for r, c, s in stars:
            print(f"{r} {c} {s}")

