import sys

def solve():
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    grid = []
    idx = 2
    for i in range(n):
        grid.append(data[idx])
        idx += 1

    # Create a mutable grid to mark stars we've covered
    covered = [['.' for _ in range(m)] for _ in range(n)]

    stars = []

    # Try to form stars at every possible center
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.' or covered[r][c] == '*':
                continue

            # Try increasing sizes
            size = 1
            while True:
                # Check if we can place a star of this size at (r, c)
                # The star occupies:
                # Center: (r, c)
                # Up: (r-k, c) for k in 1..size
                # Down: (r+k, c) for k in 1..size
                # Left: (r, c-k) for k in 1..size
                # Right: (r, c+k) for k in 1..size

                possible = True

                # Check boundaries
                if r - size < 0 or r + size >= n or c - size < 0 or c + size >= m:
                    possible = False

                # Check if all required cells are '*' in the original grid
                if possible:
                    for k in range(1, size + 1):
                        if grid[r - k][c] != '*':
                            possible = False
                        if grid[r + k][c] != '*':
                            possible = False
                        if grid[r][c - k] != '*':
                            possible = False
                        if grid[r][c + k] != '*':
                            possible = False

                if not possible:
                    break

                # If valid, add this star
                stars.append((r + 1, c + 1, size))

                # Mark the star area as covered in our 'covered' grid
                # Center
                covered[r][c] = '*'
                for k in range(1, size + 1):
                    covered[r - k][c] = '*'
                    covered[r + k][c] = '*'
                    covered[r][c - k] = '*'
                    covered[r][c + k] = '*'

                size += 1

    # Check if all '*' in the original grid are covered
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '*' and covered[r][c] != '*':
                print("-1")
                return

    print(len(stars))
    for r, c, s in stars:
        print(f"{r} {c} {s}")

if __name__ == "__main__":
    solve()
